function toggleFirstSession(id){state.firstSession=state.firstSession||[];state.firstSession=state.firstSession.includes(id)?state.firstSession.filter(x=>x!==id):[...state.firstSession,id];save();home()}
function md(src){let out='';const stack=[];const push=t=>{const reopen=out.endsWith('</li>');if(reopen)out=out.slice(0,-5);stack.push({t,reopen});out+=`<${t}>`},pop=()=>{const x=stack.pop();out+=`</${x.t}>`+(x.reopen?'</li>':'')},close=()=>{while(stack.length)pop()};for(const line of src.split('\n')){const s=line.trim(),ind=line.length-line.trimStart().length;if(!s){close();continue}const li=s.match(/^(- |\d+\. )(.*)$/);if(li){const t=li[1]==='- '?'ul':'ol',lvl=Math.min(stack.length+1,ind>=2?2:1);while(stack.length>lvl)pop();if(stack.length===lvl&&stack[lvl-1].t!==t)pop();while(stack.length<lvl)push(t);out+=`<li>${inline(li[2])}</li>`;continue}if(stack.length&&ind>=2&&out.endsWith('</li>')){out=out.slice(0,-5)+`<div class="li-more">${inline(s)}</div></li>`;continue}close();if(/^-{3,}$/.test(s)){out+='<hr>';continue}if(/^https?:/.test(s)){out+=`<p><a target="_blank" rel="noopener" href="${safeUrl(s)}">${esc(s)}</a></p>`;continue}if(s.startsWith('# ')){out+=`<h1>${esc(s.slice(2))}</h1>`;continue}if(s.startsWith('## ')){out+=`<h2 id="${slug(s.slice(3))}">${esc(s.slice(3))}</h2>`;continue}if(s.startsWith('### ')){out+=`<h3 id="${slug(s.slice(4))}">${esc(s.slice(4))}</h3>`;continue}out+=`<p>${inline(s)}</p>`}close();return out}
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function renderMath(el,n){if(el&&n>4&&window.renderMathInElement)renderMathInElement(el,{delimiters:[{left:"$$",right:"$$",display:true},{left:"$",right:"$",display:false}],throwOnError:false,ignoredTags:["script","noscript","style","textarea","pre","code","option"]})}
