function paperReset(){paperLab.reset()}
function csvParse(s){return s.trim().split(/\r?\n/).map(l=>l.split(',').map(x=>x.trim()))}
function journalTable(items){if(!items.length)return '<div class="empty">No journal entries yet. Add an entry after a paper or live activity; label it clearly.</div>';return `<div class="table-wrap"><table><thead><tr><th>Paper/live</th><th>Date / symbol</th><th>Product</th><th>Quantity</th><th>Net P/L</th><th>Decision quality</th><th>Rule followed</th><th></th></tr></thead><tbody>${items.map((x,i)=>`<tr><td>${esc(x.paper_or_live)}</td><td>${esc(x.timestamp_timezone)}<br><b>${esc(x.symbol)}</b></td><td>${esc(x.product_type)}</td><td>${esc(x.quantity)}</td><td>${esc(x.net_pnl)}</td><td>${esc(x.decision_quality)}</td><td>${esc(x.rule_followed)}</td><td><button class="button secondary small" onclick="editJournal(${state.journal.indexOf(x)})">Edit</button> <button class="button secondary small" onclick="deleteJournal(${state.journal.indexOf(x)})">Delete</button></td></tr>`).join('')}</tbody></table></div>`}
const journalFields=['paper_or_live','timestamp_timezone','symbol','venue','product_type','setup_version','equity_before','entry_planned','entry_actual','quantity','notional','margin','stop_planned','exit_planned','exit_actual','gross_pnl','fees','funding_borrow_cost','net_pnl','planned_loss_budget','rule_followed','screenshot_reference','decision_quality','notes'];
function editJournal(i){journalForm(i)}function deleteJournal(i){if(confirm('Delete this journal entry?')){state.journal.splice(i,1);save();journal()}}function filterJournal(){let q=$('#jsearch').value.toLowerCase();$('#journalRows').innerHTML=journalTable(state.journal.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(q))))}
const passportFields=['symbol','venue','legal_product','settlement_asset','quantity_unit','multiplier','minimum_size','tick_size','tick_value','session_timezone','expiry','custody','initial_margin','maintenance_margin','liquidation_reference','deficit_liability','fees','eligibility','source_url','checked_date'];
function passport(){app.innerHTML=`<div class="page-head"><div class="eyebrow">Know the product</div><h1>Product passport</h1><p>Record the product and its rules before reading the chart. Unknown is an acceptable state; a risk-critical unknown is a reason to pause.</p></div><div class="toolbar"><button class="button" onclick="passportForm()">＋ New passport</button><button class="button secondary" onclick="exportCsv('passport')">Export CSV</button></div><div class="grid grid-2">${state.passport.length?state.passport.map((x,i)=>`<div class="card"><div class="row between"><h3>${esc(x.symbol||'Unnamed product')}</h3><button class="button secondary small" onclick="editPassport(${i})">Edit</button></div><p>${esc(x.venue||'Unknown venue')} · ${esc(x.legal_product||'Unknown product type')}</p><div class="notice ${['multiplier','minimum_size','tick_size','initial_margin','maintenance_margin','liquidation_reference','deficit_liability'].some(k=>!x[k])?'warning':''}">Risk-critical fields: ${['multiplier','minimum_size','tick_size','initial_margin','maintenance_margin','liquidation_reference','deficit_liability'].filter(k=>!x[k]).map(k=>k.replaceAll('_',' ')).join(', ')||'recorded'}.</div>${isHttpUrl(x.source_url)?`<a href="${safeUrl(x.source_url)}" target="_blank" rel="noopener">Source</a>`:''}</div>`).join(''):'<div class="card empty">No product passports yet. Unknown values will be retained as Unknown.</div>'}</div>`}
function passportForm(i=-1){let x=i<0?{}:state.passport[i];app.innerHTML=`<div class="page-head"><div class="eyebrow">Editable template</div><h1>${i<0?'New':'Edit'} product passport</h1></div><div class="card"><form id="pform" class="form-grid">${passportFields.map(f=>`<div class="field"><label>${f.replaceAll('_',' ')}</label><input name="${f}" value="${esc(x[f]||'Unknown')}" placeholder="Unknown"></div>`).join('')}<div class="field full actions"><button class="button">Save passport</button><a class="button secondary" href="#passport">Cancel</a></div></form></div>`;$('#pform').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(i<0)state.passport.push(v);else state.passport[i]=v;save();location.hash='#passport';toast('Passport saved')}}function editPassport(i){passportForm(i)}
const strategyFields=['strategy_version','instrument_venue','timeframe_timezone','setup','entry_rule','stop_rule','exit_rule','sizing','no_trade_rules','regime_filter','data_source','development_period','validation_period','untouched_test_period','cost_model','slippage_model','benchmark','number_of_variants_tested','trade_count','net_expectancy','profit_factor','maximum_drawdown','rejection_criteria','remaining_uncertainty'];
function testing(){app.innerHTML=`<div class="page-head"><div class="eyebrow">Strategy notes</div><h1>Strategy testing</h1><p>Workspace only. No strategy results, historical trades or backtests have been supplied, and none are fabricated here.</p></div><div class="notice warning">Strategy labs await full course source material. This is an empty testing worksheet, not a recommendation or evidence of an edge.</div><div class="toolbar"><button class="button" onclick="strategyForm()">＋ New strategy record</button><button class="button secondary" onclick="exportCsv('strategy')">Export CSV</button></div><div class="grid grid-2">${state.strategy.length?state.strategy.map((x,i)=>`<div class="card"><h3>${esc(x.strategy_version||'Unnamed strategy')}</h3><p>${esc(x.instrument_venue||'Market/venue unknown')} · ${esc(x.timeframe_timezone||'Timeframe unknown')}</p><button class="button secondary small" onclick="editStrategy(${i})">Edit record</button></div>`).join(''):'<div class="card empty">No strategy records. Fields are ready for source-backed definitions and evidence.</div>'}</div>`}
function strategyForm(i=-1){let x=i<0?{}:state.strategy[i];app.innerHTML=`<div class="page-head"><div class="eyebrow">Strategy worksheet</div><h1>${i<0?'New':'Edit'} strategy record</h1></div><div class="card"><form id="tform" class="form-grid">${strategyFields.map(f=>`<div class="field ${['setup','entry_rule','stop_rule','exit_rule','no_trade_rules','remaining_uncertainty'].includes(f)?'full':''}"><label>${f.replaceAll('_',' ')}</label><textarea name="${f}" placeholder="Unknown / not supplied">${esc(x[f]||'')}</textarea></div>`).join('')}<div class="field full actions"><button class="button">Save</button><a class="button secondary" href="#testing">Cancel</a></div></form></div>`;$('#tform').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(i<0)state.strategy.push(v);else state.strategy[i]=v;save();location.hash='#testing'}}function editStrategy(i){strategyForm(i)}
const friendFields=['market','venue','legal_product','timeframe_timezone','setup','exact_entry_trigger','stop_invalidation','exit_rules','position_sizing','leverage','no_trade_conditions','claimed_performance','full_history_or_test_method','fees','slippage','screenshots_timestamps','missing_information'];
function friend(){app.innerHTML=`<div class="page-head"><div class="eyebrow">Review a friend’s strategy</div><h1>Friend-strategy review</h1><p>Capture the claim fairly and identify what evidence and rules are missing. This intake does not declare a strategy profitable or fraudulent.</p></div><div class="notice">The full review rubric is awaiting course material. This is an intake and review framework only.</div><div class="toolbar"><button class="button" onclick="friendForm()">＋ New submission</button><button class="button secondary" onclick="exportCsv('friend')">Export CSV</button></div><div class="grid grid-2">${state.friend.length?state.friend.map((x,i)=>`<div class="card"><h3>${esc(x.market||'Market unknown')} · ${esc(x.timeframe_timezone||'Timeframe unknown')}</h3><p>${esc(x.legal_product||'Product unknown')}</p><button class="button secondary small" onclick="editFriend(${i})">Open review</button></div>`).join(''):'<div class="card empty">No submissions. Add a strategy to generate a structured review record.</div>'}</div>`}
function friendForm(i=-1){let x=i<0?{}:state.friend[i];app.innerHTML=`<div class="page-head"><div class="eyebrow">Submission</div><h1>${i<0?'New':'Edit'} strategy submission</h1></div><div class="card"><form id="fform" class="form-grid">${friendFields.map(f=>`<div class="field ${['setup','exact_entry_trigger','stop_invalidation','exit_rules','position_sizing','no_trade_conditions','claimed_performance','full_history_or_test_method','missing_information'].includes(f)?'full':''}"><label>${f.replaceAll('_',' ')}</label><textarea name="${f}" placeholder="Unknown / not provided">${esc(x[f]||'')}</textarea></div>`).join('')}<div class="field full"><h3>Review prompts</h3><p>Fair restatement · Missing rules · Plausible mechanism vs sales story · Untestable claims · Hidden leverage · Tail-risk questions · Proposed objective test · Evidence supporting or rejecting further tests.</p></div><div class="field full actions"><button class="button">Save intake</button><a class="button secondary" href="#friend">Cancel</a></div></form></div>`;$('#fform').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(i<0)state.friend.push(v);else state.friend[i]=v;save();location.hash='#friend'}}function editFriend(i){friendForm(i)}
const resources=[['R1','How to trade with leverage in Paper Trading','TradingView','https://www.tradingview.com/support/solutions/43000742700-how-to-trade-with-leverage-in-paper-trading/','Public help article; leverage by asset class, order ticket margin details, account margin tracking. Platform subscription incentive.','Link verification carried forward; not rechecked during packaging. Simulation is not live custody.'],['R2','Margin: Know What’s Needed','CME Group','https://www.cmegroup.com/education/courses/introduction-to-futures/margin-know-what-is-needed','Public lesson on initial and maintenance margin. Futures-specific; exchange participation incentive.','Material verified in original research; no full embedded-media review claim.'],['R3','Introduction to Futures','CME Group','https://www.cmegroup.com/education/courses/introduction-to-futures','Public course: specs, expiry, settlement, ticks, notional and margin. Exchange commercial incentive.','Syllabus verified in original research; not all media reviewed.'],['R4','Micro E-mini Equity Index futures products overview','CME Group','https://www.cmegroup.com/education/courses/micro-e-mini-futures/micro-e-mini-futures-products-overview','Public lesson on multiplier/tick. Verify current specifications before use. Exchange commercial incentive.','Page material reported verified in original research.'],['R5','Types of Orders','SEC / Investor.gov','https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders','Free introductory article on market, limit and stop orders. Securities scope.','Page text retrieved in original research.'],['R6','Trading Up-Close: Stop and Stop-Limit Orders','Charles Schwab','https://www.youtube.com/watch?v=V-dnip2p3O4','Free YouTube video, 4:07. Transcript sections reported: 0:14 trigger; 0:41 stop-limit; 1:12 example; 2:43 continued-decline risk. Schwab account promotion.','Transcript retrieved in original research; visual inspection not performed.']];

function glossary(){const terms=[['Equity','Account net value including open P/L.'],['Notional','Reference market exposure represented by a position.'],['Margin','Collateral supporting exposure or obligations under applicable rules.'],['Loss budget','Planned dollar constraint, not guaranteed maximum loss.'],['Long','Exposure benefiting from higher prices in the simple model used here.'],['Tick','Minimum permitted price increment.'],['Multiplier','Value represented by one contract price point.'],['Spread','Ask minus bid for the stated quotes.'],['Slippage','Actual execution versus a specified reference price.'],['Partial fill','Less than the full order quantity executed.'],['Initial margin','Required collateral to initiate a position.'],['Maintenance margin','Required collateral/equity to maintain a position.'],['Liquidation','Forced reduction or closure under applicable rules.'],['Unrealized P/L','Profit or loss while a position remains open.'],['Asset','An item or ownership interest.'],['Derivative','A contract linked to a reference.'],['Brokerage product','The actual legal and operational wrapper offered.'],['Exchange','An organization that arranges trading.'],['Broker','An intermediary handling customer orders.'],['Market maker','A participant that quotes prices and manages inventory.'],['Clearing','Processes settlement obligations under applicable rules.'],['Custody','How an asset is held.'],['Settlement','Completion of product obligations.'],['Expiry','Termination under product specifications.'],['Bid','A buying quote.'],['Ask','A selling quote.'],['Stop-market','Order that becomes a market order after its trigger.'],['Stop-limit','Order that becomes a limit order after its stop trigger.'],['Time in force','How long an order remains active under its instructions.']];app.innerHTML=`<div class="page-head"><div class="eyebrow">Find a concept</div><h1>Glossary & search</h1><p>Definitions below are taken or lightly normalized from the supplied lesson explanations and starter glossary. No external verification is implied.</p></div><input id="gsearch" class="search" placeholder="Search glossary terms…" oninput="filterGlossary()"><div id="glossaryList" class="grid grid-2" style="margin-top:14px">${terms.map(t=>`<div class="card glossary-item"><span class="pill">From the course</span><h3 style="margin-top:9px">${esc(t[0])}</h3><p>${esc(t[1])}</p></div>`).join('')}</div><h2 class="section-title">Search lessons and resources</h2><div class="toolbar"><input id="allSearch" class="search" placeholder="Search the course…" oninput="searchCourse()"></div><div id="searchResults"></div>`}
function filterGlossary(){let q=$('#gsearch').value.toLowerCase();document.querySelectorAll('.glossary-item').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'':'none')}
function customLessonPage(id){let key=id;try{key=decodeURIComponent(id)}catch{}const x=state.customLessons.find(l=>l.id===key);if(!x){app.innerHTML='<div class="empty">Imported lesson not found.</div>';return}app.innerHTML=`<div class="page-head"><div class="eyebrow">Imported lesson · Part ${esc(x.part||'not set')}</div><h1>${esc(x.title)}</h1><p><span class="status ${x.status==='available'?'':'waiting'}">${esc(x.status)}</span> · Imported content is shown as supplied and rendered as text.</p></div><article class="lesson-body">${md(x.content)}<div class="notice">Source file: ${esc(x.sourceFile||'user import')}. Imported text is escaped before display; external source verification is not inferred.</div></article><div class="actions"><a class="button secondary" href="#course">Back to course</a></div>`}
function settings(){app.innerHTML=`<div class="page-head"><div class="eyebrow">Your data</div><h1>Data & settings</h1><p>All progress, notes, journal entries and worksheets stay in this browser’s local storage. Browser data can be cleared by the browser or device settings. Export a backup to keep a copy.</p></div><div class="card"><div class="field"><label for="displayName">Name shown on the home page (optional)</label><input id="displayName" maxlength="60" value="${esc(state.displayName||'')}" onchange="state.displayName=this.value.trim().slice(0,60);save();toast('Name saved')"></div></div><div class="grid grid-2"><div class="card"><h3>Backup and restore</h3><p>Export the academy data as JSON. Restore validates the file shape before loading it.</p><div class="actions"><button class="button" onclick="backup()">Download JSON backup</button><button class="button secondary" onclick="$('#restoreFile').click()">Restore backup</button><input id="restoreFile" type="file" accept="application/json,.json" hidden onchange="restore(event)"></div></div><div class="card"><h3>Import future lessons</h3><p>Choose a JSON file and preview lesson titles and changes before adding it. Existing notes and progress are kept. HTML is not executed.</p><div class="actions"><button class="button secondary" onclick="$('#lessonImport').click()">Choose lesson JSON</button><input id="lessonImport" type="file" accept="application/json,.json" hidden onchange="previewLessonImport(event)"></div><div id="importPreview"></div></div><div class="card"><h3>Appearance</h3><p>Choose a comfortable reading theme.</p><button class="button secondary" onclick="toggleTheme()">Switch light / dark mode</button></div><div class="card"><h3>CSV exports</h3><p>Download journal, product passport, strategy-testing or friend-strategy records. Spreadsheet formula prefixes are escaped.</p><div class="actions"><button class="button secondary small" onclick="exportCsv('journal')">Journal</button><button class="button secondary small" onclick="exportCsv('passport')">Passport</button><button class="button secondary small" onclick="exportCsv('strategy')">Strategy</button><button class="button secondary small" onclick="exportCsv('friend')">Friend intake</button></div></div><div class="card"><h3>Reset local data</h3><p>This deletes progress, notes and entries from this browser.</p><button class="button danger" onclick="resetData()">Reset with confirmation</button></div></div><div class="notice warning">No analytics or personal data are sent to third parties by the application. External resource links open their source websites when selected.</div>`}
let pendingLessonImport=[];
function previewLessonImport(e){let f=e.target.files[0];if(!f)return;if(f.size>1024*1024){toast('Lesson import is limited to 1 MB');return}let rd=new FileReader();rd.onload=()=>{try{let j=JSON.parse(rd.result),ls=Array.isArray(j)?j:j.lessons;if(!Array.isArray(ls)||!ls.length||ls.length>100)throw Error();for(let x of ls)if(!x||!/^[a-z0-9][a-z0-9_-]{0,63}$/i.test(x.id)||typeof x.title!=='string'||!x.title.trim()||typeof x.content!=='string'||!['available','awaiting material'].includes(x.status||'available'))throw Error();pendingLessonImport=ls.map(x=>({...x,status:x.status||'available',sourceFile:f.name}));$('#importPreview').innerHTML=`<div class="notice">Preview: ${pendingLessonImport.length} lesson(s). Existing IDs will have content/metadata updated; notes and progress are stored separately and will be kept.<ul>${pendingLessonImport.map(x=>`<li><b>${esc(x.title)}</b> · ${esc(x.status)} · ${state.customLessons.some(y=>y.id===x.id)?'Update existing':'New lesson'}</li>`).join('')}</ul><button class="button small" onclick="applyLessonImport()">Apply imported lessons</button></div>`}catch{$('#importPreview').innerHTML='<div class="notice warning">Invalid JSON lesson package. Each lesson needs id, title, content; optional part, stage, status. Max 100 lessons, 1 MB.</div>'}finally{e.target.value=''}};rd.readAsText(f)}
function applyLessonImport(){if(!pendingLessonImport.length){toast('Preview a valid lesson file first');return}let map=new Map(state.customLessons.map(x=>[x.id,x]));pendingLessonImport.forEach(x=>map.set(x.id,{...map.get(x.id),...x}));state.customLessons=[...map.values()];save();pendingLessonImport=[];toast('Lessons imported; notes and progress remain intact');route()}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';save();toast('Theme updated')}
function backup(){let blob=new Blob([JSON.stringify({version:AcademyMath.BACKUP_VERSION,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});download(blob,'trading-research-academy-backup.json')}
function restore(e){let f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024){toast('Backup is too large (5 MB maximum)');e.target.value='';return}let reader=new FileReader();reader.onload=()=>{try{let o=AcademyMath.migrateBackup(JSON.parse(reader.result));if(!AcademyMath.validateBackup(o))throw Error('Invalid format');state=AcademyMath.loadState({getItem:()=>JSON.stringify(o.data)},KEY,initial);save();toast('Backup restored');route()}catch(err){toast('Backup not restored: invalid file')}finally{e.target.value=''}};reader.readAsText(f)}
function resetData(){if(confirm('Reset all Trading Research Academy data in this browser? This cannot be undone unless you have a backup.')){localStorage.removeItem(KEY);state=AcademyMath.loadState({getItem:()=>null},KEY,initial);save();route();toast('Local data reset')}}
function escapeCsv(x){let s=String(x??'');if(!/^-?\d+(?:\.\d+)?(?:e[+-]?\d+)?$/i.test(s)&&/^[=+\-@\t\r]/.test(s))s="'"+s;return `"${s.replaceAll('"','""')}"`}
function exportCsv(kind){const schemas={journal:journalFields,passport:passportFields,strategy:strategyFields,friend:friendFields},data=state[kind]||[];let rows=[schemas[kind],...data.map(x=>schemas[kind].map(k=>x[k]??''))],csv=rows.map(r=>r.map(escapeCsv).join(',')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),`${kind}.csv`)}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#themeButton').onclick=toggleTheme;$('#menuButton').onclick=()=>{$('#sidebar').classList.toggle('open');let o=$('.mobile-overlay')||document.body.appendChild(Object.assign(document.createElement('div'),{className:'mobile-overlay'}));o.classList.toggle('show');o.onclick=()=>{$('#sidebar').classList.remove('open');o.classList.remove('show')}};
